    # student -> {assignment name -> grade}
    grades: Dict[str, Dict[str, float]] = field(default_factory=dict)

    KINDS = ("homework", "quiz")
    MIN_GRADE = 2.0
    MAX_GRADE = 5.0
    DEFAULT_MISSING_GRADE = 2.0

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in self.KINDS:
            raise ValueError(f"kind must be one of {self.KINDS}")
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if not (self.MIN_GRADE <= grade <= self.MAX_GRADE):
            raise ValueError(
                f"grade must be between {self.MIN_GRADE} and {self.MAX_GRADE}"
            )
        if assignment not in self.assignments:
            raise ValueError(f"unknown assignment: {assignment}")
        self.grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})
        drop = self._lowest_quiz_to_drop(student_grades)

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _) in self.assignments.items():
            if name == drop:
                continue
            grade = student_grades.get(name, self.DEFAULT_MISSING_GRADE)
            weighted_sum += weight * grade
            total_weight += weight

        return round(weighted_sum / total_weight, 2) if total_weight else 0.0

    def _lowest_quiz_to_drop(self, student_grades: Dict[str, float]) -> Optional[str]:
        """Return the lowest quiz name if more than one quiz was taken, else None."""
        quizzes_taken = [
            (name, student_grades[name])
            for name, (_, kind) in self.assignments.items()
            if kind == "quiz" and name in student_grades
        ]
        if len(quizzes_taken) <= 1:
            return None
        return min(quizzes_taken, key=lambda item: item[1])[0]
